```cpp[]
class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        vector<int>ans;
        int n = matrix.size();
        int m = matrix[0].size();
        int i=0,j;
        int total = m*n;
        for(int k = 0; k < min(m,n) & ans.size() < total; k++){
            for( j = k; j < (m-k) & ans.size() < total; j++){
                ans.push_back(matrix[i][j]);
            }
            j--;
            for( i = k+1; i < (n-k) & ans.size() < total; i++){
                ans.push_back(matrix[i][j]);
            }
            i--;
            for( j = m-(2+k); j >= k & ans.size() < total; j--){
                ans.push_back(matrix[i][j]);
            }
            j++;
            for( i = n-(2+k); i > k & ans.size() < total; i--){
                ans.push_back(matrix[i][j]);
            }
            i++;
        }
        return ans;
    }
};
```

